1	#!/usr/bin/env node
2	/**
3	 * Port of test7.py: derive two 24-byte PBKDF2 keys from one passphrase and two
4	 * different salts, printing each as lowercase hex.
5	 *
6	 *   key1 = pbkdf2.PBKDF2(a, b).read(24)   -> hex
7	 *   key2 = pbkdf2.PBKDF2(a, c).read(24)   -> hex
8	 *
9	 * Defaults inherited from the Python `pbkdf2` package: HMAC-SHA1 as the PRF and
10	 * 1000 iterations. Both are implemented from scratch under ./lib.
11	 */
12	
13	import { ArgumentParser, ParserExit } from './lib/argparse.mjs';
14	import { PBKDF2 } from './lib/pbkdf2.mjs';
15	import { toHex } from './lib/bytes.mjs';
16	
17	/** Last path component, i.e. argparse's default `prog` (basename of argv[0]). */
18	function basename(path) {
19	  const parts = String(path).split(/[/\\]/);
20	  return parts[parts.length - 1] || String(path);
21	}
22	
23	function buildParser() {
24	  const parser = new ArgumentParser({ prog: basename(process.argv[1] || 'test7.mjs') });
25	  parser.addArgument(['--a'], { required: true }); // passphrase
26	  parser.addArgument(['--b'], { required: true }); // salt1
27	  parser.addArgument(['--c'], { required: true }); // salt2
28	  return parser;
29	}
30	
31	function main() {
32	  const args = buildParser().parseArgs(process.argv.slice(2));
33	
34	  // Each PBKDF2 object is a keystream: read(24) yields T_1 (20 bytes) followed
35	  // by the first 4 bytes of T_2.
36	  const key1 = new PBKDF2(args.a, args.b).read(24);
37	  process.stdout.write(`${toHex(key1)}\n`);
38	
39	  const key2 = new PBKDF2(args.a, args.c).read(24);
40	  process.stdout.write(`${toHex(key2)}\n`);
41	}
42	
43	try {
44	  main();
45	} catch (err) {
46	  if (err instanceof ParserExit) {
47	    // Setting exitCode (rather than calling process.exit) lets the stream
48	    // drain, so piped output is never truncated.
49	    if (err.text) {
50	      if (err.stream === 'stdout') process.stdout.write(err.text);
51	      else process.stderr.write(err.text);
52	    }
53	    process.exitCode = err.code;
54	  } else {
55	    throw err;
56	  }
57	}
