#!/usr/bin/env node
// Throwaway differential-test harness: Python reference vs Node port.
// Class: hostile-chars. Uses spawnSync with an argv ARRAY (no shell).

import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test7_executable';
const PORT_ARGS = ['/output/test7.mjs'];

// ---------------------------------------------------------------- values ---
const V = {
  EMPTY: '',
  SP: ' ',
  SP3: '   ',
  TAB: '\t',
  NL: '\n',
  CR: '\r',
  CRLF: '\r\n',
  VT: '\v',
  FF: '\f',
  WS_MIX: ' \t\r\n\v\f ',
  LEAD_SP: '  lead',
  TRAIL_SP: 'trail  ',
  BOTH_SP: '  both  ',
  TAB_WRAP: '\tx\t',
  NL_EMBED: 'a\nb',
  CR_EMBED: 'a\rb',
  CRLF_EMBED: 'a\r\nb',
  SOH: '\x01',
  BEL: '\x07',
  BS: '\x08',
  ESC: '\x1b',
  ESC_SEQ: '\x1b[31mred\x1b[0m',
  DEL: '\x7f',
  CTRL_RUN: '\x01\x02\x03\x1f',
  OPT_X: '--x',
  OPT_A: '--a',
  OPT_NEG5: '-5',
  OPT_NEG: '-',
  OPT_DD: '--',
  OPT_DDD: '---',
  OPT_EQ: '--a=1',
  OPT_H: '-h',
  OPT_HELP: '--help',
  SQ: "'",
  DQ: '"',
  BOTHQ: `'"`,
  APOS: "it's",
  QUOTED: '"quoted"',
  BSL: '\\',
  BSL2: '\\\\',
  BSL_N: '\\n',
  BSL_T: '\\t',
  WINPATH: 'C:\\path\\to\\x',
  BSL_QUOTE: '\\"',
  PCT_S: '%s',
  PCT_N: '%n',
  PCT_MIX: '%s%d%x%%',
  BRACE_FMT: '{}',
  DOLLAR_PAREN: '$(id)',
  BACKTICK: '`id`',
  DOLLAR_BRACE: '${HOME}',
  DOLLAR_VAR: '$HOME',
  SEMI: '; rm -rf /',
  PIPE: 'a|b&c',
  GLOB: '*',
  GLOB2: '?[a-z]',
  TILDE: '~',
  NULWORD: 'a\\0b',
  HIGH: 'ÿ',
  ALLSAFE: '\x01\x02\x03\x04\x05\x06\x07\x08\x0b\x0c\x0e\x0f\x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\x1a\x1b\x1c\x1d\x1e\x1f\x7f',
};

// ------------------------------------------------------------ case matrix ---
const cases = [];
let seq = 0;
function add(label, argv) {
  cases.push({ n: ++seq, label, argv });
}
function triple(label, a, b, c) {
  add(label, ['--a', a, '--b', b, '--c', c]);
}

// 1. empty string in every position (single + combinations)
triple('empty:a', V.EMPTY, 'salt1', 'salt2');
triple('empty:b', 'pass', V.EMPTY, 'salt2');
triple('empty:c', 'pass', 'salt1', V.EMPTY);
triple('empty:ab', V.EMPTY, V.EMPTY, 'salt2');
triple('empty:ac', V.EMPTY, 'salt1', V.EMPTY);
triple('empty:bc', 'pass', V.EMPTY, V.EMPTY);
triple('empty:abc', V.EMPTY, V.EMPTY, V.EMPTY);
triple('empty:b=c both empty (identical salts)', 'pw', V.EMPTY, V.EMPTY);

// 2. whitespace-only in every position
triple('ws:space a', V.SP, 'salt1', 'salt2');
triple('ws:space b', 'pass', V.SP, 'salt2');
triple('ws:space c', 'pass', 'salt1', V.SP);
triple('ws:3spaces all', V.SP3, V.SP3, V.SP3);
triple('ws:tab all', V.TAB, V.TAB, V.TAB);
triple('ws:newline a', V.NL, 'salt1', 'salt2');
triple('ws:newline b', 'pass', V.NL, 'salt2');
triple('ws:newline c', 'pass', 'salt1', V.NL);
triple('ws:CR all', V.CR, V.CR, V.CR);
triple('ws:CRLF spread', V.CRLF, V.CR, V.NL);
triple('ws:VT/FF', V.VT, V.FF, V.VT);
triple('ws:mixed run', V.WS_MIX, V.WS_MIX, V.WS_MIX);
triple('ws:space vs tab distinctness', 'pw', V.SP, V.TAB);
triple('ws:empty vs space distinctness', 'pw', V.EMPTY, V.SP);

// 3. leading/trailing spaces
triple('pad:leading', V.LEAD_SP, V.LEAD_SP, V.LEAD_SP);
triple('pad:trailing', V.TRAIL_SP, V.TRAIL_SP, V.TRAIL_SP);
triple('pad:both', V.BOTH_SP, V.BOTH_SP, V.BOTH_SP);
triple('pad:tab wrap', V.TAB_WRAP, V.TAB_WRAP, V.TAB_WRAP);
triple('pad:trail vs untrimmed distinctness', 'trail', 'trail  ', 'trail');

// 4. embedded newlines / CR (output-line-splitting hazards)
triple('embed:NL', V.NL_EMBED, V.NL_EMBED, V.NL_EMBED);
triple('embed:CR', V.CR_EMBED, V.CR_EMBED, V.CR_EMBED);
triple('embed:CRLF', V.CRLF_EMBED, V.CRLF_EMBED, V.CRLF_EMBED);
triple('embed:multiline', 'line1\nline2\nline3', 's\n1', 's\r2');

// 5. control characters (no NUL - execve forbids it)
triple('ctl:SOH', V.SOH, V.SOH, V.SOH);
triple('ctl:BEL/BS', V.BEL, V.BS, V.BEL);
triple('ctl:ESC', V.ESC, V.ESC, V.ESC);
triple('ctl:ANSI seq', V.ESC_SEQ, V.ESC_SEQ, V.ESC_SEQ);
triple('ctl:DEL', V.DEL, V.DEL, V.DEL);
triple('ctl:run 01-1f', V.CTRL_RUN, V.CTRL_RUN, V.CTRL_RUN);
triple('ctl:all safe C0+DEL', V.ALLSAFE, V.ALLSAFE, 'plain');
triple('ctl:literal backslash-zero', V.NULWORD, V.NULWORD, V.NULWORD);
triple('ctl:high byte 0xff', V.HIGH, V.HIGH, V.HIGH);

// 6. option-looking values (argparse parsing hazards)
triple('opt:--x as value a', V.OPT_X, 'salt1', 'salt2');
triple('opt:--x as value b', 'pass', V.OPT_X, 'salt2');
triple('opt:--x as value c', 'pass', 'salt1', V.OPT_X);
triple('opt:-5 numeric-ish all', V.OPT_NEG5, V.OPT_NEG5, V.OPT_NEG5);
triple('opt:bare dash', V.OPT_NEG, V.OPT_NEG, V.OPT_NEG);
triple('opt:double dash value', V.OPT_DD, 'salt1', 'salt2');
triple('opt:triple dash', V.OPT_DDD, V.OPT_DDD, V.OPT_DDD);
triple('opt:--a as value', V.OPT_A, V.OPT_A, V.OPT_A);
triple('opt:-h as value', V.OPT_H, V.OPT_H, V.OPT_H);
triple('opt:--help as value', V.OPT_HELP, 'salt1', 'salt2');
triple('opt:--a=1 as value', V.OPT_EQ, V.OPT_EQ, V.OPT_EQ);
triple('opt:-5 in c only', 'pw', 's', '-5');
triple('opt:negative number-ish -1.5', '-1.5', '-1.5', '-1.5');

// 6b. equals-form and separator-form flag syntax with hostile payloads
add('syn:equals empty', ['--a=', '--b=', '--c=']);
add('syn:equals spaces', ['--a= ', '--b=\t', '--c=\n']);
add('syn:equals dashes', ['--a=--x', '--b=-5', '--c=--']);
add('syn:after -- separator', ['--a', 'p', '--b', 's1', '--', '--c', 's2']);
add('syn:-- then dashy value', ['--a', 'p', '--b', 's1', '--c', '--', '--']);
add('syn:duplicate --a last wins', ['--a', 'first', '--a', '--x', '--b', 's1', '--c', 's2']);
add('syn:abbrev --a only', ['--a', 'p', '--b', 's1', '--c', 's2']);
add('syn:missing value for --c', ['--a', 'p', '--b', 's1', '--c']);
add('syn:missing --c entirely', ['--a', 'p', '--b', 's1']);
add('syn:no args', []);
add('syn:only --', ['--']);
add('syn:extra positional hostile', ['--a', 'p', '--b', 's1', '--c', 's2', '--x']);
add('syn:extra positional empty', ['--a', 'p', '--b', 's1', '--c', 's2', '']);
add('syn:unknown flag with newline', ['--a', 'p', '--b', 's1', '--c', 's2', '--z\nz']);

// 7. quotes
triple('q:single quote', V.SQ, V.SQ, V.SQ);
triple('q:double quote', V.DQ, V.DQ, V.DQ);
triple('q:both quotes', V.BOTHQ, V.BOTHQ, V.BOTHQ);
triple('q:apostrophe word', V.APOS, V.APOS, V.APOS);
triple('q:quoted word', V.QUOTED, V.QUOTED, V.QUOTED);
triple('q:mixed quote/space', `' "  '`, `"' '"`, `'`);

// 8. backslashes
triple('bs:single', V.BSL, V.BSL, V.BSL);
triple('bs:double', V.BSL2, V.BSL2, V.BSL2);
triple('bs:literal \\n', V.BSL_N, V.BSL_N, V.BSL_N);
triple('bs:literal \\t', V.BSL_T, V.BSL_T, V.BSL_T);
triple('bs:windows path', V.WINPATH, V.WINPATH, V.WINPATH);
triple('bs:escaped quote', V.BSL_QUOTE, V.BSL_QUOTE, V.BSL_QUOTE);
triple('bs:real tab vs literal', V.TAB, V.BSL_T, V.TAB);

// 9. format-string payloads
triple('fmt:%s', V.PCT_S, V.PCT_S, V.PCT_S);
triple('fmt:%n', V.PCT_N, V.PCT_N, V.PCT_N);
triple('fmt:mixed', V.PCT_MIX, V.PCT_MIX, V.PCT_MIX);
triple('fmt:braces', V.BRACE_FMT, '{0}', '{a!r}');
triple('fmt:percent-s in usage-triggering pos', V.PCT_S, 's', '%(prog)s');

// 10. shell metacharacters (must be inert under argv-array spawn)
triple('sh:$(id)', V.DOLLAR_PAREN, V.DOLLAR_PAREN, V.DOLLAR_PAREN);
triple('sh:backtick', V.BACKTICK, V.BACKTICK, V.BACKTICK);
triple('sh:${HOME}', V.DOLLAR_BRACE, V.DOLLAR_BRACE, V.DOLLAR_BRACE);
triple('sh:$HOME', V.DOLLAR_VAR, V.DOLLAR_VAR, V.DOLLAR_VAR);
triple('sh:semicolon rm', V.SEMI, V.SEMI, V.SEMI);
triple('sh:pipe/amp', V.PIPE, V.PIPE, V.PIPE);
triple('sh:glob', V.GLOB, V.GLOB2, V.TILDE);
triple('sh:newline injection', 'a\nid\n', 'b\n$(id)\n', 'c\n`id`\n');

// 11. long / repeated hostile
triple('long:1000 spaces', ' '.repeat(1000), ' '.repeat(1000), ' '.repeat(999));
triple('long:mixed hostile x200', '\t\n\\"%s$( '.repeat(200), 'x', 'y');
triple('long:newlines x100', '\n'.repeat(100), '\r'.repeat(100), '\r\n'.repeat(50));

// 12. cross-field distinctness (b vs c must produce different lines)
triple('distinct:b/c whitespace variants', 'pw', ' ', '  ');
triple('distinct:b/c NL vs CR', 'pw', '\n', '\r');
triple('distinct:b/c CRLF vs LFCR', 'pw', '\r\n', '\n\r');
triple('distinct:b/c bsl vs bsl2', 'pw', '\\', '\\\\');

// ------------------------------------------------------------------ run ---
function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], {
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, PATH: process.env.PATH, COLUMNS: '80', TERM: 'dumb' },
    cwd: '/tmp/dt7',
  });
  if (r.error) return { err: String(r.error), status: null, stdout: Buffer.alloc(0), stderr: Buffer.alloc(0) };
  return {
    status: r.status,
    signal: r.signal,
    stdout: r.stdout ?? Buffer.alloc(0),
    stderr: r.stderr ?? Buffer.alloc(0),
  };
}

const esc = (s) =>
  JSON.stringify(s).replace(/[�-]/g, (ch) => '\\x' + ch.charCodeAt(0).toString(16).padStart(2, '0'));
const showArgv = (a) => '[' + a.map(esc).join(', ') + ']';
const showBuf = (b) => (b.length === 0 ? '<empty>' : esc(b.toString('utf8')));
const hex = (b) => (b.length === 0 ? '<empty>' : b.toString('hex'));

// The reference is a PyInstaller binary named `test7_executable`; the port runs
// as `test7.mjs`. argparse embeds prog in usage/error text. Track that
// separately so a pure argv[0] artifact isn't confused with a semantic bug.
const normalize = (b) =>
  Buffer.from(b.toString('binary').split('test7_executable').join('PROG').split('test7.mjs').join('PROG'), 'binary');

let pass = 0;
const mismatches = [];
const progOnly = [];

for (const c of cases) {
  const ref = run(REF, [], c.argv);
  const port = run('node', PORT_ARGS, c.argv);

  const soEq = Buffer.compare(ref.stdout, port.stdout) === 0;
  const seEq = Buffer.compare(ref.stderr, port.stderr) === 0;
  const rcEq = ref.status === port.status;

  if (soEq && seEq && rcEq) {
    pass++;
    continue;
  }

  const nSoEq = Buffer.compare(normalize(ref.stdout), normalize(port.stdout)) === 0;
  const nSeEq = Buffer.compare(normalize(ref.stderr), normalize(port.stderr)) === 0;
  const rec = { c, ref, port, soEq, seEq, rcEq, nSoEq, nSeEq };
  if (nSoEq && nSeEq && rcEq) progOnly.push(rec);
  else mismatches.push(rec);
}

const dump = (title, list) => {
  if (!list.length) return;
  console.log(`\n===== ${title} (${list.length}) =====`);
  for (const { c, ref, port, soEq, seEq, rcEq } of list) {
    console.log(`\n--- case #${c.n} [${c.label}] ---`);
    console.log(`argv           : ${showArgv(c.argv)}`);
    console.log(`exit  ref/port : ${ref.status} / ${port.status}   ${rcEq ? 'OK' : '<<< DIFFERS'}`);
    if (!soEq) {
      console.log(`stdout ref     : ${showBuf(ref.stdout)}`);
      console.log(`stdout port    : ${showBuf(port.stdout)}`);
      console.log(`stdout hex ref : ${hex(ref.stdout)}`);
      console.log(`stdout hex port: ${hex(port.stdout)}`);
    } else {
      console.log(`stdout         : identical (${ref.stdout.length} bytes)`);
    }
    if (!seEq) {
      console.log(`stderr ref     : ${showBuf(ref.stderr)}`);
      console.log(`stderr port    : ${showBuf(port.stderr)}`);
    } else {
      console.log(`stderr         : identical (${ref.stderr.length} bytes)`);
    }
  }
};

dump('REAL MISMATCHES', mismatches);
dump('PROG-NAME-ONLY DIFFS (argv[0] artifact)', progOnly);

console.log(`\n===== SUMMARY =====`);
console.log(`total cases      : ${cases.length}`);
console.log(`exact matches    : ${pass}`);
console.log(`prog-name-only   : ${progOnly.length}`);
console.log(`real mismatches  : ${mismatches.length}`);

